class Solution {
  public int oddEvenJumps(int[] arr) {
    int n = arr.length, count = 1;
    boolean[] oddJump = new boolean[n];
    boolean[] evenJump = new boolean[n];

    TreeMap<Integer, Integer> map = new TreeMap();
    map.put(arr[n - 1], n - 1);
    oddJump[n - 1] = true;
    evenJump[n - 1] = true;

    for (int i = n - 2; i >= 0; i--) {
      Map.Entry<Integer, Integer> hi = map.ceilingEntry(arr[i]);
      Map.Entry<Integer, Integer> lo = map.floorEntry(arr[i]);
      if (hi != null) {
        oddJump[i] = evenJump[hi.getValue()];
      }

      if (lo != null) {
        evenJump[i] = oddJump[lo.getValue()];
      }

      if (oddJump[i]) count++;
      map.put(arr[i], i);
    }

    return count;
  }
}
